function simulateTrueClick(selector) {
    const element = document.querySelector(selector);
    if (!element) {
        console.error("[❌] العنصر مش موجود، تأكد من الـ Selector يا هندسة.");
        return;
    }

    // 1. حساب الإحداثيات الديناميكية للعنصر على الشاشة في اللحظة الحالية
    const rect = element.getBoundingClientRect();

    // 2. توليد إحداثيات عشوائية ذكية جوة حدود الزرار (تبان كأنها ضغطة بشري مش في المنتصف بالظبط)
    const paddingX = rect.width * 0.2;
    const paddingY = rect.height * 0.2;
    const clientX = rect.left + paddingX + Math.random() * (rect.width - 2 * paddingX);
    const clientY = rect.top + paddingY + Math.random() * (rect.height - 2 * paddingY);

    const screenX = window.screenX + clientX;
    const screenY = window.screenY + clientY;

    // 3. إعدادات الحدث (Event Options) تحاكي الماوس الحقيقي
    const eventOptions = {
        bubbles: true,
        cancelable: true,
        composed: true,
        view: window,
        detail: 1,
        clientX: clientX,
        clientY: clientY,
        screenX: screenX,
        screenY: screenY,
        button: 0,
        buttons: 1,
        pointerId: 1,
        isPrimary: true,
        width: 1,
        height: 1,
        pressure: 0.5
    };

    // 4. مصفوفة الأحداث بالترتيب الطبيعي للـ Browser
    const eventTypes = [
        { type: 'pointerdown', class: PointerEvent },
        { type: 'mousedown', class: MouseEvent },
        { type: 'pointerup', class: PointerEvent },
        { type: 'mouseup', class: MouseEvent },
        { type: 'click', class: MouseEvent }
    ];

    // 5. إطلاق الأحداث ورا بعض بفارق زمني بسيط جداً (Microtask)
    eventTypes.forEach(({ type, class: EventClass }) => {
        const ev = new EventClass(type, eventOptions);
        element.dispatchEvent(ev);
    });

    console.log(`%c[✔] تم إرسال الضغطة بنجاح ديناميكياً!`, "color: green; font-weight: bold;");
    console.log(`📍 الإحداثيات: X=${clientX.toFixed(2)}, Y=${clientY.toFixed(2)}`);
}

